import{_ as t,c as a,o,a2 as i}from"./chunks/framework.mqLGQ42V.js";const c=JSON.parse('{"title":"时间轴 (Timeline) - Rive 编辑器","description":"Rive 界面显示了一个带有播放控制的时间轴，以及用于在动画模式下进行当前动画配置的选项。时间轴左侧显示了所有动画的列表。请记住，这些都是当前活动画板 (Artboard)的动画。 单次播放 (One-Shot)： 播放头在动画结束时停止。","frontmatter":{"title":"时间轴 (Timeline) - Rive 编辑器","description":"Rive 界面显示了一个带有播放控制的时间轴，以及用于在动画模式下进行当前动画配置的选项。时间轴左侧显示了所有动画的列表。请记住，这些都是当前活动画板 (Artboard)的动画。 单次播放 (One-Shot)： 播放头在动画结束时停止。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 动画模式, 时间轴"}]]},"headers":[],"relativePath":"editor/animate-mode/timeline.md","filePath":"editor/animate-mode/timeline.md","lastUpdated":1774867914000}'),n={name:"editor/animate-mode/timeline.md"};function r(l,e,s,m,d,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<p>动画模式</p><h1 id="时间轴-timeline" tabindex="-1">时间轴 (Timeline) <a class="header-anchor" href="#时间轴-timeline" aria-label="Permalink to &quot;时间轴 (Timeline)&quot;">​</a></h1><p>Rive 界面显示了一个带有播放控制的时间轴，以及用于在动画模式下进行当前动画配置的选项。时间轴左侧显示了所有动画的列表。请记住，这些都是当前活动<a href="/docs/editor/fundamentals/artboards#active-artboard">画板 (Artboard)</a>的动画。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 时间轴 Pn)</p></blockquote><h2 id="​-动画类型-animation-type" tabindex="-1"><a href="#animation-type">​</a> 动画类型 (Animation type) <a class="header-anchor" href="#​-动画类型-animation-type" aria-label="Permalink to &quot;[​](#animation-type) 动画类型 (Animation type)&quot;">​</a></h2><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 动画类型 Pn) <strong>单次播放 (One-Shot)：</strong> 播放头在动画结束时停止。 <strong>乒乓播放 (Ping-Pong)：</strong> 播放头持续从起点播放到终点，再从终点播放回起点。 <strong>循环播放 (Loop)：</strong> 播放头持续在起点和终点之间循环播放动画。 <strong>工作区域 (Work Area)：</strong> 工作区域定义了动画的播放范围。通过工作区域，可以轻松地专注于长动画中的一小部分。</p></blockquote><h2 id="​-导航时间轴-navigate-timeline" tabindex="-1"><a href="#navigate-timeline">​</a> 导航时间轴 (Navigate Timeline) <a class="header-anchor" href="#​-导航时间轴-navigate-timeline" aria-label="Permalink to &quot;[​](#navigate-timeline) 导航时间轴 (Navigate Timeline)&quot;">​</a></h2><p>导航时间轴菜单提供了一系列有用的快捷键，帮助你在时间轴中自由穿梭。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 导航时间轴 Pn)</p></blockquote><h2 id="​-仅显示选中项-show-only-selected" tabindex="-1"><a href="#show-only-selected">​</a> 仅显示选中项 (Show Only Selected) <a class="header-anchor" href="#​-仅显示选中项-show-only-selected" aria-label="Permalink to &quot;[​](#show-only-selected) 仅显示选中项 (Show Only Selected)&quot;">​</a></h2><p>在处理具有大量关键帧对象的动画时，“仅显示选中项”开关非常有用。开启此选项后，时间轴上只会显示你当前选中的对象。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 仅显示选中项 Pn)</p></blockquote><h2 id="​-时间轴选项-timeline-options" tabindex="-1"><a href="#timeline-options">​</a> 时间轴选项 (Timeline Options) <a class="header-anchor" href="#​-时间轴选项-timeline-options" aria-label="Permalink to &quot;[​](#timeline-options) 时间轴选项 (Timeline Options)&quot;">​</a></h2><p>时间轴选项位于播放选择器的右侧，显示了当前时间、持续时间、播放速度和关键帧吸附选项。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 时间轴选项 Pn) <strong>当前 (Current)：</strong> 播放头的当前位置。 <strong>持续时间 (Duration)：</strong> 时间轴的总长度。 <strong>播放速度 (Playback Speed)：</strong> 动画播放的速度。默认速度为 1x。负值会导致动画倒着播放。 <strong>吸附关键帧 (Snap Keys)：</strong> 可以在时间轴上放置关键帧的间隔。默认情况下，关键帧可以设置为每秒 60 帧的细分点。</p></blockquote><h2 id="​-在时间轴中导航" tabindex="-1"><a href="#navigating-the-timeline">​</a> 在时间轴中导航 <a class="header-anchor" href="#​-在时间轴中导航" aria-label="Permalink to &quot;[​](#navigating-the-timeline) 在时间轴中导航&quot;">​</a></h2><p><strong>滚动与缩放 (Scroll and Zoom)：</strong> 使用时间轴顶部带有两个调节柄的水平滚动条来滚动和调整时间轴的缩放级别。 <strong>平移 (Pan)：</strong> 你也可以使用与舞台相同的平移快捷键来平移时间轴（右键点击并拖拽，或者按住空格键并拖拽）。</p><p><a href="/docs/editor/animate-mode/overview">概览 (Overview)</a><a href="/docs/editor/animate-mode/keyframes">关键帧 (Keys)</a></p>',18)])])}const g=t(n,[["render",r]]);export{c as __pageData,g as default};
